/* Navigation behavior — generated by sitereal. A hand edit here is kept: sitereal asks before writing over it. */
(() => {
  const P = (name) => '[data-nav-part="' + name + '"]';
  const FOCUSABLE = 'a[href], button:not([disabled]), input, select, textarea, [tabindex]:not([tabindex="-1"])';
  let uid = 0;

  /* Is this nav in its mobile state? Whatever the stylesheet says: the toggle
     is displayed below the breakpoint and hidden above it, so asking whether
     it is visible asks the CSS where the breakpoint is. No configuration, and
     nothing to keep in sync with the media query you actually edit. */
  const isMobile = (nav) => {
    const toggle = nav.querySelector(':scope > ' + P('toggle'));
    return !!toggle && toggle.offsetParent !== null;
  };

  /* Held open by the builder while it is being styled. The canvas takes
     clicks for selecting elements, so nothing there can be clicked open; it
     stamps the open state onto the menu instead and marks it held, and the
     only thing asked of the script is to stop closing it. Never on a page —
     it is put on the DOM of a preview, not into the document we write. */
  const held = (nav) => nav.hasAttribute('data-nav-peek');

  /* An entry is a dropdown when it holds a trigger — there is no separate
     kind of node for it, which is the point: put a trigger and a submenu in
     an item and it opens, take them out and it doesn't. */
  const dropdowns = (nav) =>
    [...nav.querySelectorAll(P('item'))].filter((el) => el.querySelector(':scope > ' + P('trigger')));

  const triggerOf = (item) => item.querySelector(':scope > ' + P('trigger'));
  /* What a trigger opens: a submenu or a mega panel. To everything below
     this line they are the same thing, which is why swapping one for the
     other needs nothing but the swap. */
  const subOf = (item) => item.querySelector(':scope > ' + P('sub') + ', :scope > ' + P('mega'));

  function setItem(item, open) {
    /* One choke point for closing an entry, so being held open survives every
       way there is to close one — a click away, Escape, a resize past the
       breakpoint. Opening is never blocked: what is held open is already. */
    if (!open && held(item.closest(P('nav')) || item)) return;
    if (open) { fit(item); place(item); }
    item.toggleAttribute('data-nav-open', open);
    const trigger = triggerOf(item);
    if (trigger) trigger.setAttribute('aria-expanded', String(open));
  }

  const closeItems = (nav, except) => {
    for (const item of dropdowns(nav)) if (item !== except) setItem(item, false);
  };

  /* The style a dropdown opens in (data-nav-drop). An inline one is an
     accordion in the flow of the list: opening it moves everything under it,
     so it never opens on hover — the page would jump as the pointer crossed
     it — and a click elsewhere is not a reason to fold it shut. */
  const dropOf = (item) => item.getAttribute('data-nav-drop') || '';

  /* A full-width mega panel spans the screen, and its containing block is the
     menu — which sits wherever the header put it. So the panel is told, as
     two custom properties, how far its start edge is from the screen's and
     how wide the screen is; the CSS reads them with the menu's own width as
     the fallback, so a page whose script never ran gets a menu-wide panel
     rather than a broken one. "The screen" is the page's own box: the
     document on a site, the frame in the builder (a shadow root's host). The
     ratio undoes any scaling the page is drawn under. */
  function fit(item) {
    if (dropOf(item) !== 'full') return;
    const panel = subOf(item);
    const box = panel && panel.offsetParent;
    if (!box) return;
    const root = item.getRootNode();
    const frame = root && root.host ? root.host : document.documentElement;
    const f = frame.getBoundingClientRect();
    const b = box.getBoundingClientRect();
    /* offsetWidth is rounded to a whole pixel, so the ratio is only trusted
       when the page really is drawn scaled (the builder's zoom); otherwise
       it would put the panel a fraction of a pixel off the edge. */
    const ratio = box.offsetWidth ? b.width / box.offsetWidth : 1;
    const scale = Math.abs(ratio - 1) < 0.02 ? 1 : ratio;
    const rtl = getComputedStyle(box).direction === 'rtl';
    const start = rtl ? (b.right - f.right) / scale : (f.left - b.left) / scale;
    panel.style.setProperty('--nav-full-start', start + 'px');
    panel.style.setProperty('--nav-full-size', frame.clientWidth + 'px');
  }
  const fitAll = (nav) => { for (const item of dropdowns(nav)) fit(item); };

  /* A submenu that would open past the right edge opens leftwards instead.
     Measured rather than guessed — it depends on where the nav happens to sit
     — and on every opening, however it was opened: a click and a keyboard
     reach the edge of the screen as surely as a mouse does. A side flyout
     starts at the trigger's far edge rather than its near one, so that is the
     edge it is measured from. */
  function place(item) {
    const sub = subOf(item);
    if (!sub || item.hasAttribute('data-nav-align')) return;
    const box = item.getBoundingClientRect();
    const from = dropOf(item) === 'side' ? box.right : box.left;
    item.toggleAttribute('data-nav-flip', from + sub.offsetWidth > window.innerWidth);
  }

  /* Focus what was just revealed — on the next frame, not this one. Both the
     submenu and the panel are hidden with `visibility`, and an element the
     browser still considers invisible cannot take focus: calling focus() in
     the same tick as the attribute that shows it silently does nothing, and
     the keyboard is left standing on the trigger. */
  const focusWhenShown = (el) => { if (el) requestAnimationFrame(() => el.focus()); };

  /* Scroll lock is counted, not toggled: two navs on a page (a header and a
     footer one) must not have the first one closing undo the second's lock. */
  let locks = 0;
  function lockScroll(on) {
    locks = Math.max(0, locks + (on ? 1 : -1));
    document.documentElement.style.overflow = locks ? 'hidden' : '';
  }

  /** Tie a control to the thing it opens, with a real id and a real
      aria-controls. Done here rather than in the markup because only here is
      there something to point at that is guaranteed unique on the page. */
  function wire(control, target) {
    if (!control || !target) return;
    if (!target.id) target.id = 'nav-' + (uid += 1);
    control.setAttribute('aria-controls', target.id);
    if (!control.hasAttribute('aria-expanded')) control.setAttribute('aria-expanded', 'false');
  }

  function init(nav) {
    if (nav.dataset.navReady) return;
    nav.dataset.navReady = '1';

    const toggle = nav.querySelector(':scope > ' + P('toggle'));
    const panel = nav.querySelector(':scope > ' + P('panel'));
    const scrim = nav.querySelector(':scope > ' + P('scrim'));
    const closers = panel ? [...panel.querySelectorAll(P('close'))] : [];
    let locked = false;

    wire(toggle, panel);

    function setPanel(open) {
      if (!open && held(nav)) return;
      if (nav.hasAttribute('data-nav-open') === open) return;
      nav.toggleAttribute('data-nav-open', open);
      if (toggle) toggle.setAttribute('aria-expanded', String(open));
      /* The panel is only modal while it is the off-canvas sheet — that is,
         while the menu is in its mobile state. Locking the page's scroll for
         a desktop menu that changes nothing would be a lie about what is
         reachable. */
      const modal = isMobile(nav);
      if (modal && open !== locked) { lockScroll(open); locked = open; }
      if (!open) {
        closeItems(nav);
        if (locked) { lockScroll(false); locked = false; }
      }
      if (open && modal) focusWhenShown(panel && panel.querySelector(FOCUSABLE));
    }

    const closePanel = (focusToggle) => {
      if (!nav.hasAttribute('data-nav-open')) return;
      setPanel(false);
      if (focusToggle && toggle) toggle.focus();
    };

    if (toggle) toggle.addEventListener('click', () => setPanel(!nav.hasAttribute('data-nav-open')));
    if (scrim) scrim.addEventListener('click', () => closePanel(true));
    for (const c of closers) c.addEventListener('click', () => closePanel(true));

    for (const item of dropdowns(nav)) {
      const trigger = triggerOf(item);
      const sub = subOf(item);
      wire(trigger, sub);
      if (!trigger) continue;

      /* Hover opens it, but only where there is a real pointer: on a touch
         screen :hover sticks after a tap and the menu would open itself — and
         not at all when the dropdown has been told it opens on click, which is
         what a panel big enough to sit over the page usually wants. */
      const openOn = () => item.getAttribute('data-nav-open-on') || '';
      const byHover = () => openOn() !== 'click';
      /* And the other way round: told to open on hover, the trigger stops
         toggling — clicking a menu the pointer is still inside would close it
         under the cursor. Only where hovering is actually how this reader
         opens it, though: a tap, a mobile menu and a keyboard have no hover
         to open with, and a dropdown you cannot open is not a setting. */
      const byClick = (e) => openOn() !== 'hover'
        || isMobile(nav)
        || !e.detail                                        // Enter or Space
        || (e.pointerType && e.pointerType !== 'mouse')     // a tap or a pen
        || !matchMedia('(hover: hover)').matches;

      trigger.addEventListener('click', (e) => {
        e.preventDefault();
        if (!byClick(e)) return;
        const open = !item.hasAttribute('data-nav-open');
        // one open flyout at a time with a mouse; a phone list — or an
        // accordion, which is one at every width — may stay open
        if (!isMobile(nav) && dropOf(item) !== 'inline') closeItems(nav, item);
        setItem(item, open);
      });
      trigger.addEventListener('keydown', (e) => {
        if (e.key !== 'ArrowDown') return;
        e.preventDefault();
        setItem(item, true);
        /* Scoped by walking to the submenu first: FOCUSABLE is a list of
           selectors, and prefixing the string would only scope the first of
           them — which is how you end up focusing the trigger you just left. */
        focusWhenShown(sub && sub.querySelector(FOCUSABLE));
      });
      item.addEventListener('pointerenter', (e) => {
        if (e.pointerType !== 'mouse' || isMobile(nav) || !byHover() || dropOf(item) === 'inline') return;
        closeItems(nav, item);
        setItem(item, true);
      });
      item.addEventListener('pointerleave', (e) => {
        if (e.pointerType !== 'mouse' || isMobile(nav) || !byHover() || dropOf(item) === 'inline') return;
        setItem(item, false);
      });
    }

    /* Keyboard, once, for the whole nav: Escape closes the nearest thing that
       is open and puts focus back where it came from — a menu that closes and
       drops you at the top of the page is a menu you have to re-navigate. */
    nav.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const open = nav.querySelector('[data-nav-open]');
        if (open && open !== nav) {
          const trigger = triggerOf(open);
          setItem(open, false);
          if (trigger) trigger.focus();
          e.stopPropagation();
          return;
        }
        closePanel(true);
        return;
      }
      /* Focus trap — only while the panel is actually a modal sheet. Tabbing
         out of a desktop menu is meant to reach the page. */
      if (e.key === 'Tab' && nav.hasAttribute('data-nav-open') && isMobile(nav) && panel) {
        const stops = [toggle, ...panel.querySelectorAll(FOCUSABLE)].filter((x) => x && x.offsetParent !== null);
        if (!stops.length) return;
        const first = stops[0];
        const last = stops[stops.length - 1];
        const active = nav.getRootNode().activeElement;
        if (e.shiftKey && active === first) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && active === last) { e.preventDefault(); first.focus(); }
      }
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        const sub = e.target.closest && e.target.closest(P('sub'));
        if (!sub) return;
        const links = [...sub.querySelectorAll(FOCUSABLE)];
        const at = links.indexOf(e.target);
        if (at < 0) return;
        e.preventDefault();
        const next = links[(at + (e.key === 'ArrowDown' ? 1 : -1) + links.length) % links.length];
        if (next) next.focus();
      }
    });

    /* Clicking away closes whatever is open. Guarded on the nav still being
       in the document, so a stale listener from a re-render is a no-op. */
    document.addEventListener('pointerdown', (e) => {
      if (!nav.isConnected || nav.contains(e.target)) return;
      for (const item of dropdowns(nav)) if (dropOf(item) !== 'inline') setItem(item, false);
      if (!isMobile(nav)) closePanel(false);
    });

    /* Following a link inside the menu should leave the menu behind. */
    if (panel) {
      panel.addEventListener('click', (e) => {
        const a = e.target.closest && e.target.closest('a[href]');
        if (a && !a.closest(P('trigger'))) closePanel(false);
      });
    }

    /* Crossing the breakpoint changes what everything means, so the nav goes
       back to rest rather than carrying a phone's open panel onto a desktop. */
    let wasMobile = isMobile(nav);
    fitAll(nav);
    window.addEventListener('resize', () => {
      if (!nav.isConnected) return;
      fitAll(nav);
      const now = isMobile(nav);
      if (now === wasMobile) return;
      wasMobile = now;
      closeItems(nav);
      setPanel(false);
    });

    /* Which entry is the page you are on. Read from the URL at runtime, so no
       page has to be told about the nav. Another site's address is never the
       page you are on, and a link to one's root has a pathname of '/' — which
       is the homepage's, so the origin has to be part of the question. A link
       with a fragment goes to a section of a page, not to the page — on a
       one-page site every `/#visit` and `#about` is the page you are on, and
       marking them all current says nothing. */
    const here = location.pathname.replace(/\/+$/, '') || '/';
    for (const a of nav.querySelectorAll('a[href]')) {
      if (a.closest(P('skip'))) continue;
      if (a.getAttribute('href').includes('#')) continue;
      let url;
      try { url = new URL(a.getAttribute('href'), location.href); } catch { continue; }
      if (url.origin !== location.origin) continue;
      if ((url.pathname.replace(/\/+$/, '') || '/') !== here) continue;
      a.setAttribute('aria-current', 'page');
    }
  }

  const start = () => { for (const nav of document.querySelectorAll('[data-nav-part="nav"]')) init(nav); };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
